select distinct ev.* from eg_voucher ev inner join eg_voucher_entry eve on ev.id = eve.voucher_id where 1 = 1 and ev.del_flag = '0' and eve.del_flag = '0'
and ev.org_id = #{param.orgId}
and ev.scene_code = #{param.sceneCode}
and eve.contract_code = #{param.contractCode}

with table1 as ( select ev.period_code , ev.org_id, eoc.org_name , eve.account_code , ea.account_name , sum(coalesce (eve.debit_amount, 0)) debit_amount, sum(coalesce(eve.credit_amount, 0)) credit_amount , SUM(coalesce(eve.credit_amount, 0)) - SUM(coalesce(eve.debit_amount, 0)) as diff_amount, case when SUM(coalesce(eve.credit_amount, 0)) - SUM(coalesce(eve.debit_amount, 0)) = 0 then '否' else '是' end as is_exception from eg_voucher_entry eve inner join eg_voucher ev on eve.voucher_id = ev.id and ev.del_flag = '0' left join eg_org_company eoc on eoc.org_id = ev.org_id and eoc.del_flag ='0' left join eg_account ea on ea.account_code = eve.account_code and ea.del_flag ='0' where eve.del_flag = '0'
and ev.voucher_date >= #{param.periodCodeStart}
and ev.voucher_date <= #{param.periodCodeEnd}
and ev.period_code = #{param.periodCode} and eve.period_code = #{param.periodCode}
and eve.account_code = '2241.20'
and ev.org_id in
#{item}
group by ev.period_code , ev.org_id, eoc.org_name, eve.account_code, ea.account_name ) select count(1) as totalCount from table1 where 1=1
and table1.isException = #{param.isException}

with table1 as ( select ev.period_code , ev.org_id, eoc.org_name , eve.account_code , ea.account_name , sum(coalesce (eve.debit_amount, 0)) debit_amount, sum(coalesce(eve.credit_amount, 0)) credit_amount , SUM(coalesce(eve.credit_amount, 0)) - SUM(coalesce(eve.debit_amount, 0)) as diff_amount, case when SUM(coalesce(eve.credit_amount, 0)) - SUM(coalesce(eve.debit_amount, 0)) = 0 then '否' else '是' end as is_exception from eg_voucher_entry eve inner join eg_voucher ev on eve.voucher_id = ev.id and ev.del_flag = '0' left join eg_org_company eoc on eoc.org_id = ev.org_id and eoc.del_flag ='0' left join eg_account ea on ea.account_code = eve.account_code and ea.del_flag ='0' where eve.del_flag = '0'
and ev.voucher_date >= #{param.periodCodeStart}
and ev.voucher_date <= #{param.periodCodeEnd}
and ev.period_code = #{param.periodCode} and eve.period_code = #{param.periodCode}
and eve.account_code = '2241.20'
and ev.org_id in
#{item}
group by ev.period_code , ev.org_id, eoc.org_name, eve.account_code, ea.account_name ) select table1.period_code , table1.org_id, table1.org_name , table1.account_code , table1.account_name , table1.debit_amount, table1.credit_amount , table1.diff_amount, table1.is_exception from table1 where 1=1
and table1.isException = #{param.isException}
order by table1.period_code , table1.org_id limit #{param.limit} offset #{param.offset}
